const s=wb.getWorksheet('RS.Food');
const before=s.getRange('K6:K607').getValues().map(r=>r[0]);
s.getRange('K6:K607').setFormulas(Array.from({length:602},(_,n)=>{const r=n+6; return [`=IF(J${r}="","",SUMPRODUCT((I${r}=$I$6:$I$1500)*(B${r}<$B$6:$B$1500))+SUMPRODUCT((I${r}=$I$6:I${r})*(B${r}=$B$6:B${r})))`]}));
const v=s.getRange('A6:K607').getValues();
const g={}; let changed=[]; let nonNum=0, blanks=0;
v.forEach((r,i)=>{const k=r[10]; if(k===''||k==null){blanks++;return} if(typeof k!=='number'){nonNum++;return} (g[r[8]]??=[]).push({row:i+6,a:r[0],b:r[1],k}); if(k!==before[i])changed.push([i+6,r[0],r[8],r[1],before[i],k])});
const check=Object.entries(g).map(([c,x])=>{const ks=x.map(y=>y.k).sort((a,b)=>a-b); const seq=ks.every((k,i)=>k===i+1); const srt=[...x].sort((a,b)=>a.k-b.k); const mono=srt.every((y,i)=>i===0||srt[i-1].b>y.b||(srt[i-1].b===y.b&&srt[i-1].row<y.row)); return [c,x.length,seq,mono]});
log(JSON.stringify(check)); log('blanks',blanks,'nonNum',nonNum,'changed',changed.length); log(JSON.stringify(changed));
log(s.getRange('K6').getCell().getFormula?.()); log(s.getRange('K607').getFormula?.());
log(JSON.stringify(s.getRange('K176:K180').getValues())); log(s.getRange('R7:U29').getStats?.());
const errs=s.getRange('K6:K607').getValues().flat().filter(x=>typeof x==='object'&&x!==null).length; log('errs',errs, s.getRange('K6').getStyle?.().getNumberFormat?.());
s.getRange('R7:U27')

